/**
 * Factory for building organism attributes from external species configuration.
 *
 * @version 2022.03.02
 */
public final class ConfiguredAttributes
{
    private ConfiguredAttributes()
    {
    }

    public static OrganismAttributes organism(Species species, OrganismFactory factory,
                                              BreedingStrategy breedingStrategy,
                                              RelocationStrategy relocationStrategy,
                                              OrganismActionCommand... actionCommands)
    {
        SpeciesConfig config = SpeciesConfigurationLoader.getConfig(species);
        return new OrganismAttributes(species, config.isDiurnal(),
                                      config.getBreedingAge(), config.getMaxAge(),
                                      config.getBreedingProbability(),
                                      config.getMaxLitterSize(), factory,
                                      breedingStrategy, relocationStrategy,
                                      actionCommands);
    }

    public static AnimalAttributes animal(Species species, OrganismFactory factory,
                                          BreedingStrategy breedingStrategy,
                                          RelocationStrategy relocationStrategy,
                                          OrganismActionCommand... actionCommands)
    {
        SpeciesConfig config = SpeciesConfigurationLoader.getConfig(species);
        Integer maxHealth = config.getMaxHealth();
        if(maxHealth == null) {
            throw new IllegalStateException("Missing maxHealth for animal species " + species);
        }

        return new AnimalAttributes(species, config.isDiurnal(),
                                    config.getBreedingAge(), config.getMaxAge(),
                                    config.getBreedingProbability(),
                                    config.getMaxLitterSize(), maxHealth.intValue(),
                                    factory, config.getFoodSources(),
                                    breedingStrategy, relocationStrategy,
                                    actionCommands);
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Collections;
import java.util.EnumMap;
import java.util.LinkedHashSet;
import java.util.Properties;
import java.util.Set;

/**
 * Loads species configuration from an external properties file.
 *
 * @version 2022.03.02
 */
public final class SpeciesConfigurationLoader
{
    private static final String CONFIG_FILE = "organism-config.properties";
    private static final EnumMap<Species, SpeciesConfig> CONFIGS = loadConfigs();

    private SpeciesConfigurationLoader()
    {
    }

    public static SpeciesConfig getConfig(Species species)
    {
        SpeciesConfig config = CONFIGS.get(species);
        if(config == null) {
            throw new IllegalStateException("Missing config for species " + species);
        }
        return config;
    }

    private static EnumMap<Species, SpeciesConfig> loadConfigs()
    {
        Properties properties = new Properties();
        try (InputStream stream = openConfig()) {
            properties.load(stream);
        }
        catch (IOException e) {
            throw new IllegalStateException("Unable to load " + CONFIG_FILE, e);
        }

        EnumMap<Species, SpeciesConfig> configs = new EnumMap<>(Species.class);
        for(Species species : Species.values()) {
            configs.put(species, loadSpeciesConfig(species, properties));
        }
        return configs;
    }

    private static InputStream openConfig() throws IOException
    {
        InputStream classpathStream =
            SpeciesConfigurationLoader.class.getResourceAsStream("/" + CONFIG_FILE);
        if(classpathStream != null) {
            return classpathStream;
        }

        Path path = Paths.get(CONFIG_FILE);
        if(Files.exists(path)) {
            return Files.newInputStream(path);
        }

        throw new IOException("Configuration file not found: " + CONFIG_FILE);
    }

    private static SpeciesConfig loadSpeciesConfig(Species species, Properties properties)
    {
        String prefix = species.getConfigKey() + ".";
        boolean diurnal = readBoolean(properties, prefix + "diurnal");
        int breedingAge = readInt(properties, prefix + "breedingAge");
        int maxAge = readInt(properties, prefix + "maxAge");
        double breedingProbability = readDouble(properties, prefix + "breedingProbability");
        int maxLitterSize = readInt(properties, prefix + "maxLitterSize");
        double creationProbability = readDouble(properties, prefix + "creationProbability");
        Integer maxHealth = readOptionalInt(properties, prefix + "maxHealth");
        Set<Species> foodSources = readSpeciesSet(properties, prefix + "foodSources");

        return new SpeciesConfig(diurnal, breedingAge, maxAge,
                                 breedingProbability, maxLitterSize,
                                 creationProbability,
                                 maxHealth, foodSources);
    }

    private static boolean readBoolean(Properties properties, String key)
    {
        return Boolean.parseBoolean(readRequired(properties, key));
    }

    private static int readInt(Properties properties, String key)
    {
        return Integer.parseInt(readRequired(properties, key));
    }

    private static Integer readOptionalInt(Properties properties, String key)
    {
        String value = properties.getProperty(key);
        if(value == null || value.trim().length() == 0) {
            return null;
        }
        return Integer.valueOf(Integer.parseInt(value.trim()));
    }

    private static double readDouble(Properties properties, String key)
    {
        return Double.parseDouble(readRequired(properties, key));
    }

    private static Set<Species> readSpeciesSet(Properties properties, String key)
    {
        String value = properties.getProperty(key);
        if(value == null || value.trim().length() == 0) {
            return Collections.emptySet();
        }

        Set<Species> speciesSet = new LinkedHashSet<>();
        String[] values = value.split(",");
        for(String item : values) {
            speciesSet.add(Species.valueOf(item.trim().toUpperCase()));
        }
        return speciesSet;
    }

    private static String readRequired(Properties properties, String key)
    {
        String value = properties.getProperty(key);
        if(value == null) {
            throw new IllegalStateException("Missing required config key: " + key);
        }
        return value.trim();
    }
}

import java.util.*;
/**
 * A singleton Weather object that will hold different types
 * of weather. Each different weather has their own modifier
 * that will affect how animal's behave, notably whether
 * they are successful in finding food.
 *
 * @version 2022.03.02
 */
public class Weather
{
    // A shared random object
    private static final Random rand = Randomizer.getRandom();

    // Hashmap that contain the weather and the hunting modifier for that weather
    private HashMap<String, Double> weatherAndModifier = new HashMap<String, Double>();
    // The current weather of the Weather object
    private String currentWeather;
    // Singleton instance of the Weather object
    private static Weather instance;

    public Weather() {
        weatherAndModifier.put("Sunny", 1.0);
        weatherAndModifier.put("Rainy", 0.7);
        weatherAndModifier.put("Foggy", 0.5);
    }

    public static Weather getWeather() {
        if (instance == null) {
            instance = new Weather();
        }
        return instance;
    }

    // Accessor and mutator methods

    /**
     * Return the current weather
     * 
     * @return String of the current weather
     */
    public String getCurrentWeather() {
        return currentWeather;
    }

    /**
     * Returns the hunting modifier of the current weather
     * 
     * @return double representing the hunting modifier
     */
    public double getWeatherModifier() {
        return weatherAndModifier.get(currentWeather);
    }

    /**
     * Set the current weather explicitly
     * 
     * @param String the desired weather
     */
    public void setWeather(String newWeather) {
        currentWeather = newWeather;
    }

    // Functional methods

    /**
     * Resets the current weather to "Sunny"
     */
    public void resetWeather() {
        currentWeather = "Sunny";
    }

    /**
     * Changes the weather of the Weather object to a random state
     */
    public void changeWeather() {
        Object[] weatherKeys = weatherAndModifier.keySet().toArray();
        int randomNumber = rand.nextInt(weatherKeys.length);
        currentWeather = (String) weatherKeys[randomNumber];
    }
}

/**
 * Centralizes the event rules that control time-of-day and weather changes.
 *
 * @version 2022.03.02
 */
public class SimulationRulesEngine
{
    private static final int DAY_NIGHT_CYCLE_LENGTH = 80;
    private static final int DAYLIGHT_DURATION = 55;
    private static final int WEATHER_CHANGE_INTERVAL = 450;

    private final Weather weather;

    public SimulationRulesEngine()
    {
        this(Weather.getWeather());
    }

    public SimulationRulesEngine(Weather weather)
    {
        this.weather = weather;
    }

    /**
     * Apply step-based environment events such as periodic weather changes.
     *
     * @param step The simulation step being executed.
     */
    public void applyStepEvents(int step)
    {
        if (step % WEATHER_CHANGE_INTERVAL == 0) {
            weather.changeWeather();
        }
    }

    /**
     * Determine whether an organism should act during the current step.
     *
     * @param organism The organism being considered.
     * @param step The current simulation step.
     * @return True if the organism is active this step.
     */
    public boolean canAct(Organism organism, int step)
    {
        return getTimeOfDay(step).matches(organism.isDiurnal());
    }

    /**
     * Return the time-of-day phase for the given step.
     *
     * @param step The current simulation step.
     * @return The time-of-day phase.
     */
    public TimeOfDay getTimeOfDay(int step)
    {
        if (step % DAY_NIGHT_CYCLE_LENGTH <= DAYLIGHT_DURATION) {
            return TimeOfDay.DAY;
        }
        return TimeOfDay.NIGHT;
    }

    /**
     * Return the weather label for the current environment.
     *
     * @return The current weather name.
     */
    public String getCurrentWeather()
    {
        return weather.getCurrentWeather();
    }

    /**
     * Set the weather explicitly.
     *
     * @param weatherName The new weather to apply.
     */
    public void setWeather(String weatherName)
    {
        weather.setWeather(weatherName);
    }

    /**
     * Reset the event rules to their initial state.
     */
    public void reset()
    {
        weather.resetWeather();
    }
}

