  6	/**
  7	 * A simple predator-prey simulator, based on a rectangular field
  8	 * containing rabbits and foxes.
  9	 * 
 10	 * @version 2022.03.02
 11	 */
 12	public class Simulator
 13	{
 14	    // Constants representing configuration information for the simulation.
 15	    // The default width for the grid.
 16	    private static final int DEFAULT_WIDTH = 120;
 17	    // The default depth of the grid.
 18	    private static final int DEFAULT_DEPTH = 80;
 19	    // List of animals in the field.
 20	    private List<Organism> organisms;
 21	    // The current state of the field.
 22	    private Field field;
 23	    // The current step of the simulation.
 24	    private int step;
 25	    // A graphical view of the simulation.
 26	    private SimulationDisplay view;
 27	    // Centralized engine for weather and time-of-day event rules.
 28	    private SimulationRulesEngine rules;
 29	    // Rules describing the main animal population.
 30	    private final PopulationRule[] primaryPopulationRules;
 31	    // Rules describing slower secondary occupants when no primary animal appears.
 32	    private final PopulationRule[] secondaryPopulationRules;
 33	    
 34	    /**
 35	     * Construct a simulation field with default size.
 36	     */
 37	    public Simulator()
 38	    {
 39	        this(new SimulationContainer(), DEFAULT_DEPTH, DEFAULT_WIDTH, false);
 40	    }
 41	    
 42	    /**
 43	     * Create a simulation field with the given size.
 44	     * @param depth Depth of the field. Must be greater than zero.
 45	     * @param width Width of the field. Must be greater than zero.
 46	     */
 47	    public Simulator(int depth, int width)
 48	    {
 49	        this(new SimulationContainer(), depth, width, false);
 50	    }
 51	
 52	    public Simulator(SimulationContainer container, int depth, int width)
 53	    {
 54	        this(container, depth, width, false);
 55	    }
 56	
 57	    /**
 58	     * Create a simulation field with the given size using a headless display.
 59	     * @param depth Depth of the field. Must be greater than zero.
 60	     * @param width Width of the field. Must be greater than zero.
 61	     * @return A simulator that never instantiates Swing UI objects.
 62	     */
 63	    public static Simulator createHeadless(int depth, int width)
 64	    {
 65	        return new Simulator(new SimulationContainer(), depth, width, true);
 66	    }
 67	
 68	    /**
 69	     * Create a simulation field with the given size.
 70	     * @param depth Depth of the field. Must be greater than zero.
 71	     * @param width Width of the field. Must be greater than zero.
 72	     * @param headless If true, a headless display is always used.
 73	     */
 74	    public static Simulator createHeadless(SimulationContainer container,
 75	                                           int depth, int width)
 76	    {
 77	        return new Simulator(container, depth, width, true);
 78	    }
 79	
 80	    private Simulator(SimulationContainer container, int depth, int width,
 81	                      boolean headless)
 82	    {
 83	        if(width <= 0 || depth <= 0) {
 84	            System.out.println("The dimensions must be greater than zero.");
 85	            System.out.println("Using default values.");
 86	            depth = DEFAULT_DEPTH;
 87	            width = DEFAULT_WIDTH;
 88	        }
 89	        
 90	        organisms = new ArrayList<>();
 91	        field = new Field(depth, width);
 92	        rules = container.getRulesEngine();
 93	        primaryPopulationRules = container.getPrimaryPopulationRules();
 94	        secondaryPopulationRules = container.getSecondaryPopulationRules();
 95	
 96	        // Create a view of the state of each location in the field.
 97	        this.view = container.createDisplay(depth, width, headless);
 98	        for(PopulationRule rule : primaryPopulationRules) {
 99	            this.view.setColor(rule.getSpecies(), rule.getColor());
100	        }
101	        for(PopulationRule rule : secondaryPopulationRules) {
102	            this.view.setColor(rule.getSpecies(), rule.getColor());
103	        }
104	        
105	        // Setup a valid starting point.
106	        reset();
107	    }
108	    
109	    // Accessor and mutator methods
110	    
111	    /**
112	     * Return the current step number of the simulation
113	     * 
114	     * @return int of the current step in the simulation
115	     */
116	    public int getStepNumber()
117	    {
118	        return step;
119	    }
120	
121	    /**
122	     * Return an immutable view of the current simulation state.
123	     *
124	     * @return The current simulation state.
125	     */
126	    public SimulationState getState()
127	    {
128	        FieldSnapshot snapshot = field.createSnapshot();
129	        return new SimulationState(step, snapshot,
130	                                   rules.getCurrentWeather(),
131	                                   rules.getTimeOfDay(step),
132	                                   snapshot.getActiveSpeciesCount() > 1);
133	    }
134	
135	    /**
136	     * Return a snapshot of the field without updating the display.
137	     *
138	     * @return The current field snapshot.
139	     */
140	    public FieldSnapshot getFieldSnapshot()
141	    {
142	        return getState().getFieldSnapshot();
143	    }
144	
145	    /**
146	     * Determine whether the simulation is still viable.
147	     *
148	     * @return True if more than one species is alive.
149	     */
150	    public boolean isViable()
151	    {
152	        return getState().isViable();
153	    }
154	    
155	    // Functional methods
156	    
157	    /**
158	     * Run the simulation from its current state for a reasonably long period,
159	     * (4000 steps).
160	     */
161	    public void runLongSimulation()
162	    {
163	        simulate(4000);
164	    }
165	    
166	    /**
167	     * Run the simulation from its current state for the given number of steps.
168	     * Stop before the given number of steps if it ceases to be viable.
169	     * @param numSteps The number of steps to run for.
170	     */
171	    public void simulate(int numSteps)
172	    {
173	        for(int step = 1; step <= numSteps && isViable(); step++) {
174	            simulateOneStep();
175	            //delay(60);   // uncomment this to run more slowly
176	        }
177	    }
178	    
179	    /**
180	     * Run the simulation from its current state for a single step.
181	     * Iterate over the whole field updating the state of each
182	     * fox and rabbit.
183	     */
184	    public void simulateOneStep()
185	    {
186	        step++;
187	        rules.applyStepEvents(step);
188	        // Provide space for newborn animals.
189	        List<Organism> newOrganisms = new ArrayList<>();        
190	        // Let all rabbits act.
191	        for(Iterator<Organism> it = organisms.iterator(); it.hasNext(); ) {
192	            Organism organism = it.next();
193	            
194	            if (rules.canAct(organism, step)) {
195	                organism.act(newOrganisms);
196	            }
197	            if(! organism.isAlive()) {
198	                it.remove();
199	            }
200	        }
201	                   
202	        // Add the newly born organisms to the main lists.
203	        organisms.addAll(newOrganisms);
204	        view.showStatus(getState());
205	    }
206	        
207	    /**
208	     * Reset the simulation to a starting position.
209	     */
210	    public void reset()
211	    {
212	        step = 0;
213	        organisms.clear();
214	        populate();
215	        rules.reset();
216	        
217	        // Show the starting state in the view.
218	        view.showStatus(getState());
219	    }
