  1	import java.io.IOException;
  2	import java.io.InputStream;
  3	import java.nio.file.Files;
  4	import java.nio.file.Path;
  5	import java.nio.file.Paths;
  6	import java.util.Collections;
  7	import java.util.EnumMap;
  8	import java.util.LinkedHashSet;
  9	import java.util.Properties;
 10	import java.util.Set;
 11	
 12	/**
 13	 * Loads species configuration from an external properties file.
 14	 *
 15	 * @version 2022.03.02
 16	 */
 17	public class PropertiesSpeciesConfigurationRepository
 18	    implements SpeciesConfigurationRepository
 19	{
 20	    private final String configFile;
 21	    private final EnumMap<Species, SpeciesConfig> configs;
 22	
 23	    public PropertiesSpeciesConfigurationRepository(String configFile)
 24	    {
 25	        this.configFile = configFile;
 26	        configs = loadConfigs();
 27	    }
 28	
 29	    public SpeciesConfig getConfig(Species species)
 30	    {
 31	        SpeciesConfig config = configs.get(species);
 32	        if(config == null) {
 33	            throw new IllegalStateException("Missing config for species " + species);
 34	        }
 35	        return config;
 36	    }
 37	
 38	    private EnumMap<Species, SpeciesConfig> loadConfigs()
 39	    {
 40	        Properties properties = new Properties();
 41	        try (InputStream stream = openConfig()) {
 42	            properties.load(stream);
 43	        }
 44	        catch (IOException e) {
 45	            throw new IllegalStateException("Unable to load " + configFile, e);
 46	        }
 47	
 48	        EnumMap<Species, SpeciesConfig> loadedConfigs = new EnumMap<>(Species.class);
 49	        for(Species species : Species.values()) {
 50	            loadedConfigs.put(species, loadSpeciesConfig(species, properties));
 51	        }
 52	        return loadedConfigs;
 53	    }
 54	
 55	    private InputStream openConfig() throws IOException
 56	    {
 57	        InputStream classpathStream =
 58	            getClass().getResourceAsStream("/" + configFile);
 59	        if(classpathStream != null) {
 60	            return classpathStream;
 61	        }
 62	
 63	        Path path = Paths.get(configFile);
 64	        if(Files.exists(path)) {
 65	            return Files.newInputStream(path);
 66	        }
 67	
 68	        throw new IOException("Configuration file not found: " + configFile);
 69	    }
 70	
 71	    private SpeciesConfig loadSpeciesConfig(Species species, Properties properties)
 72	    {
 73	        String prefix = species.getConfigKey() + ".";
 74	        boolean diurnal = readBoolean(properties, prefix + "diurnal");
 75	        int breedingAge = readInt(properties, prefix + "breedingAge");
 76	        int maxAge = readInt(properties, prefix + "maxAge");
 77	        double breedingProbability = readDouble(properties, prefix + "breedingProbability");
 78	        int maxLitterSize = readInt(properties, prefix + "maxLitterSize");
 79	        double creationProbability = readDouble(properties, prefix + "creationProbability");
 80	        Integer maxHealth = readOptionalInt(properties, prefix + "maxHealth");
 81	        Set<Species> foodSources = readSpeciesSet(properties, prefix + "foodSources");
 82	
 83	        return new SpeciesConfig(diurnal, breedingAge, maxAge,
 84	                                 breedingProbability, maxLitterSize,
 85	                                 creationProbability, maxHealth, foodSources);
 86	    }
 87	
 88	    private boolean readBoolean(Properties properties, String key)
 89	    {
 90	        return Boolean.parseBoolean(readRequired(properties, key));
 91	    }
 92	
 93	    private int readInt(Properties properties, String key)
 94	    {
 95	        return Integer.parseInt(readRequired(properties, key));
 96	    }
 97	
 98	    private Integer readOptionalInt(Properties properties, String key)
 99	    {
100	        String value = properties.getProperty(key);
101	        if(value == null || value.trim().length() == 0) {
102	            return null;
103	        }
104	        return Integer.valueOf(Integer.parseInt(value.trim()));
105	    }
106	
107	    private double readDouble(Properties properties, String key)
108	    {
109	        return Double.parseDouble(readRequired(properties, key));
110	    }
111	
112	    private Set<Species> readSpeciesSet(Properties properties, String key)
113	    {
114	        String value = properties.getProperty(key);
115	        if(value == null || value.trim().length() == 0) {
116	            return Collections.emptySet();
117	        }
118	
119	        Set<Species> speciesSet = new LinkedHashSet<>();
120	        String[] values = value.split(",");
121	        for(String item : values) {
122	            speciesSet.add(Species.valueOf(item.trim().toUpperCase()));
123	        }
124	        return speciesSet;
125	    }
126	
127	    private String readRequired(Properties properties, String key)
128	    {
129	        String value = properties.getProperty(key);
130	        if(value == null) {
131	            throw new IllegalStateException("Missing required config key: " + key);
132	        }
133	        return value.trim();
134	    }
135	}

