  4	/**
  5	 * A class representing shared characteristics of all animals within the simultion.
  6	 * Animals will find food, have a gender and be able to become infected.
  7	 * 
  8	 * @version 2022.03.02
  9	 */
 10	public abstract class Animal extends Organism
 11	{
 12	    // Shared lifecycle and diet settings for this animal's species.
 13	    private final AnimalAttributes attributes;
 14	    // Shared weather state provided by the simulation container.
 15	    private final Weather weather;
 16	    // Gender of the animal
 17	    private boolean isMale;
 18	    // Current health of the animal
 19	    private int currentHealth;
 20	    // Whether the animal is infected
 21	    private boolean isInfected;
 22	    
 23	    /**
 24	     * Create a new animal at location in field.
 25	     * 
 26	     * @param field The field currently occupied.
 27	     * @param location The location within the field.
 28	     */
 29	    public Animal(boolean randomAge, Field field, Location location,
 30	                  AnimalAttributes attributes, Weather weather)
 31	    {
 32	        super(randomAge, field, location, attributes);
 33	        this.attributes = attributes;
 34	        this.weather = weather;
 35	        
 36	        if (randomAge) {
 37	            currentHealth = getRand().nextInt(attributes.getMaxHealth());
 38	        }
 39	        if (getRand().nextInt(2) == 0) {
 40	            isMale = true;
 41	        }
 42	        else {
 43	            isMale = false;
 44	        }
 45	        
 46	        isInfected = false;
 47	    }
 48	    
 49	    // Accessor and mutator methods
 50	    
 51	    /**
 52	     * Returns whether the animal is male
 53	     * 
 54	     * @boolean True if the animal is male, false if animal is female
 55	     */
 56	    protected boolean getGender()
 57	    {
 58	        return isMale;
 59	    }
 60	    
 61	    /**
 62	     * Return whether the animal is infected
 63	     * 
 64	     * @return True if the animal is infected, false if not
 65	     */
 66	    protected boolean getIsInfected() {
 67	        return isInfected;
 68	    }
 69	    
 70	    /**
 71	     * Sets the animal to infected state
 72	     */
 73	    protected void infect() {
 74	        isInfected = true;
 75	    }
 76	
 77	    /**
 78	     * Checks if the animal can breed
 79	     * 
 80	     * @return true if the animal can breed
 81	     */
 82	    protected boolean hasBreedingMate()
 83	    {
 84	        if (isMale == false)
 85	        {
 86	            Field field = getField();
 87	            List<Location> adjacent = field.adjacentLocations(getLocation());
 88	            Iterator<Location> it = adjacent.iterator();
 89	            while (it.hasNext())
 90	            {
 91	                Location where = it.next();
 92	                Organism organism = (Organism) field.getOccupantAt(where);
 93	                if (organism != null && organism.getSpecies() == getSpecies())
 94	                {
 95	                    Animal animal = (Animal) organism;
 96	                    return animal.getGender() == true
 97	                        && getAge() >= getAttributes().getBreedingAge();
 98	                }
 99	            }
100	        }
101	        return false;
102	    }
103	
104	    /**
105	     * A method that will make the animal object search the adjacent squares around it,
106	     * then find and eat an eligible food source.
107	     */
108	    protected Location findFood()
109	    {
110	        Field field = getField();
111	        List<Location> adjacent = field.adjacentLocations(getLocation());
112	        Iterator<Location> it = adjacent.iterator();
113	        while(it.hasNext()) {
114	            Location where = it.next();
115	            Organism target = (Organism) field.getOccupantAt(where);
116	            if (target != null) {
117	                if (attributes.getFoodSources().contains(target.getSpecies())
118	                    && target.isAlive()
119	                    && getRand().nextDouble() <= weather.getWeatherModifier()) {
120	                    target.setDead();
121	                    currentHealth = attributes.getMaxHealth();
122	                }
123	            }
124	        }
125	        return null;
126	    }
127	    
128	    /**
129	     * Decrease this animal's. This could result in the animal's death by hunger.
130	     */
131	    protected void incrementHealth()
132	    {
133	        currentHealth--;
134	        if(currentHealth == 0) {
135	            setDead();
136	        }
137	    }
138	
139	}
